using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.GroupAlgebra;

internal sealed class PGroupProjectiveDimensionDocument : IScribeDocumentDefinition
{
    private static readonly LibraryNoteRef Webb =
        LibraryNoteRef.Create("D5/L/FiniteGroups/webb2016pgroups");

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Norm preimages and fixed-vector detection characterize projectivity at the modular invariant dimension bound.",
        H("Projectivity at the Invariant Dimension Bound"),
        Blocks(Describe.Lean(
            DescribeId.Create("modular-p-group-projective-invariant-dimension-criterion"),
            DeclarationHandle.Create("D5/S3/FiniteGroups/GroupAlgebra/PGroupProjectiveDimension.projective_iff_finrank_eq_card_mul_finrank_invariants"),
            H("Equality holds exactly for projective representations"),
            StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(Webb),
            Blocks(
                Paragraph(Text("Let p be prime, k any field of characteristic p, P any finite p-group, and rho a representation of P on a finite-dimensional k-vector space V. Then rho.asModule is projective over the actual group algebra k[P] if and only if dim_k V equals |P| times dim_k rho.invariants. The field, group and vector space occupy independent universes. P can be nonabelian, k can be infinite and need not be algebraically closed, V can be zero, and P can be trivial. Finite-dimensionality of V is an actual hypothesis: discarding all dimension hypotheses and using finrank would be false because infinite-dimensional finrank is zero.")),
                Paragraph(Text("Write W for the invariant subspace. For any k-vector space U define R(U) as the functions P to U with T_g(f)(h) equal to f(h times g). The private rightTranslate definition verifies this left action using associativity alone: T_g composed with T_a evaluates f at h times g times a. An invariant function is constant, since evaluating T_h(f) equals f at the identity gives f(h) equals f(1). The private invariant_function_constant is consumed both in the norm-preimage construction and in the proof of injectivity below.")),
                Paragraph(Text("The private orbitSum construction takes an ordinary k-linear map L from U to V to an equivariant map q_L from R(U) to V, defined by q_L(f) equal to the sum over a in P of rho(a)(L(f(a inverse))). Reindexing a by g times a proves q_L(T_g(f)) equals rho(g)(q_L(f)); the inner argument becomes (g times a) inverse times g, which equals a inverse. The delta function at 1 with value u maps to L(u). A constant function with value u maps to Representation.norm rho applied to L(u). These are the live orbitSum_delta and orbitSum_constant calculations. The existing norm is the unnormalised sum of the representation operators; no division by |P| occurs.")),
                Paragraph(Text("The regular-function module is genuinely free. For finite-dimensional U choose the actual Module.finBasis b, indexed by i in Fin(dim_k U). The private rightTranslate_free builds a k-linear equivalence E from R(U) to the coefficient space of Representation.free k P i. The coefficient of group element a in its ith coordinate is b.equivFun(f(a inverse))(i). It uses Finsupp.linearEquivFunOnFinite, MonoidAlgebra.coeffLinearEquiv and LinearEquiv.piCongrRight, and proves equivariance with the actual leftRegular coefficient action and free representation. Under right translation this coefficient becomes b.equivFun(f(a inverse times g))(i); under the left regular action it is evaluated at g inverse times a, whose inverse is a inverse times g. In the scalar case the construction sends delta_x to the group basis element x inverse. This inverse is necessary for nonabelian P.")),
                Paragraph(Text("Representation.IntertwiningMap.equivLinearMapAsModule converts the resulting intertwiner to a k[P]-linear bijection. LinearEquiv.ofBijective bundles it as a module equivalence, and Representation.free_asModule_free together with Module.Free.of_equiv' transfers the existing free module structure. The pointwise action calculation in free_apply_coordinate is a private consumed helper. This route uses the established regular/free representations and never applies a commutative-ring local-ring theorem to k[P].")),
                Paragraph(Text("For the forward implication, projectivity supplies the norm preimages. Take U equal to V and L equal to the identity, so q from R(V) to V is surjective because q(delta_1(v)) equals v. Convert q to a k[P]-linear map and use Module.projective_lifting_property to split q by a map s from V to R(V). The same intertwining/module-map equivalence recovers its equivariance. If v is invariant, then s(v) is invariant, hence constant with value x equal to s(v)(1). Therefore v equals q(s(v)), equals q(constant x), equals norm_rho(x). This is the private invariant_norm_preimage proof. Since V is finite-dimensional, R(V) is the finite regular free module described above; the lifting calculation itself only needs the explicitly proved surjectivity of q.")),
                Paragraph(Text("Choose a basis b_i of W and a norm preimage x_i of every b_i. Basis.constr assembles x_i into an ordinary linear map L from W to V. Representation.self_norm_apply shows the norm takes values in W, so LinearMap.codRestrict bundles N from V to W. Checking on the basis gives N composed with L equal to the identity on W. In particular norm_rho(L(w)) equals the underlying vector w for every w in W. The map Phi equal to q_L from the regular free module R(W) to V sends the constant function with value w to w. Thus its restriction to the invariant functions has zero kernel; it in fact identifies their invariant bases.")),
                Paragraph(Text("The new injection inference is the private injective_of_invariant_kernel. For any equivariant linear map f from a modular P-representation, assume its invariant kernel is zero. If its full kernel contained a nonzero x, regard the actual intertwiner kernel as a Subrepresentation and apply PGroupInvariants.exists_nonzero_mem_invariants_of_isPGroup to that restricted representation with x. It yields a nonzero kernel vector y fixed under the restricted action. Subrepresentation.toRepresentation_apply_coe transports its fixed equations to the ambient representation. The assumed invariant-kernel equation forces y to be zero, a contradiction. This proves injectivity without asserting that a submodule containing all invariants is the whole space.")),
                Paragraph(Text("Apply that kernel argument to Phi. It gives an injection from R(W) to V, so |P| times dim_k W is at most dim_k V. Independently, PGroupInvariantEmbedding.exists_injective_linearMap_invariants_rightTranslate supplies an injection F from V to R(W), so dim_k V is at most |P| times dim_k W. Module.finrank_pi_fintype computes the latter dimension with independent universes, and LinearMap.finrank_le_finrank_of_injective proves each inequality. Antisymmetry yields the required equality. The empty invariant basis is handled by the same construction: if W is zero the saved embedding forces V to be zero. No separate nonzero-dimension hypothesis is introduced.")),
                Paragraph(Text("Conversely, suppose dim_k V equals |P| times dim_k W. Reuse the existing invariant embedding F with its exact identity F(rho(g)(v))(h) equal to F(v)(h times g). The target has equal finite dimension, so LinearMap.injective_iff_surjective_of_finrank_eq_finrank makes F surjective as well as injective. Bundle its translation identity into an intertwiner, convert it to a k[P]-linear bijection, and obtain a module equivalence. The previously proved rightTranslate_free makes the target free. Free modules are projective, and Module.Projective.of_equiv' transfers projectivity to rho.asModule. Thus equality produces an actual isomorphism with a regular free module, completing the reverse implication.")),
                Paragraph(Text("The saved embedding itself uses an ordinary vector-space retraction onto W, not an equivariant retraction: it sends v to the function h mapping to r(rho(h)(v)). Its kernel vanishes by the fixed-vector argument. The present proof consumes that embedding for its injection and translation identity. Its fixed-vector prerequisite comes from the nilpotent augmentation ideal; no averaging, semisimple decomposition, finite-field assumption, abelian or cyclic reduction, Frobenius-algebra framework or injective-envelope theorem is added.")),
                Paragraph(Text("Transient anonymous Lean application checks cover V equal to zero, P equal to the trivial group, the regular representation, and the nonzero trivial representation of dimension |P| when P is nontrivial. For the regular representation the norm element has coefficient one at every group element and spans a one-dimensional invariant subspace, so equality is sharp even if its augmentation is zero. For the trivial representation of dimension d equal to |P|, the invariant dimension is d, and d is not |P| times d because d is positive and |P| is greater than one. Its dimension is nevertheless divisible by |P|. This shows that mere divisibility by the group order is insufficient for projectivity. The zero-space, trivial-group, regular-representation and characteristic-two trivial-action cases are checked transiently against the criterion, with no named specialization or companion theorem retained. The last example refutes projectivity despite divisibility; it does not refute an original claim of dimension divisibility, since divisibility holds in this example.")),
                Paragraph(Text("All helpers are private and consumed by the single public criterion. The constructions are structural rather than bounded enumeration, numerical reduction, a checker or a certified finite instance, hence utility none. Bounded source intake in the pinned RepresentationTheory paths did not identify a general projective invariant-equals-norm-range theorem to reuse; this does not establish exhaustive absence from all libraries. The norm, lifting, free representation, finite-dimensional and intertwining APIs are reused directly. The norm-retract mechanism and the projective criterion are classical. The Pro argument was fallible mathematical advice, not source verification or an exact citation. The acknowledged Webb note supports the augmentation-nilpotence input; it is not claimed to state this full exact telescope. The Lean proof uses the existing compiled prerequisites and explicit coercion and coefficient calculations. Kernel preparation and native Scribe emission do not constitute independent review, admission, freezing or official acceptance."))),
            DescribeRole.Theorem))));
}
